import{_ as e,o,c as t,ae as s}from"./chunks/framework.BZFOeXrC.js";const u=JSON.parse('{"title":"系统与部署","description":"","frontmatter":{},"headers":[],"relativePath":"systems.md","filePath":"systems.md","lastUpdated":null}'),i={name:"systems.md"};function l(r,a,d,c,n,h){return o(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="系统与部署" tabindex="-1">系统与部署 <a class="header-anchor" href="#系统与部署" aria-label="Permalink to &quot;系统与部署&quot;">​</a></h1><h2 id="linux、git、python-c-与-gpu-开发环境" tabindex="-1">Linux、Git、Python/C++ 与 GPU 开发环境 <a class="header-anchor" href="#linux、git、python-c-与-gpu-开发环境" aria-label="Permalink to &quot;Linux、Git、Python/C++ 与 GPU 开发环境&quot;">​</a></h2><h2 id="数据、日志与实验复现" tabindex="-1">数据、日志与实验复现 <a class="header-anchor" href="#数据、日志与实验复现" aria-label="Permalink to &quot;数据、日志与实验复现&quot;">​</a></h2><h3 id="lerobotdataset-设计" tabindex="-1">LeRobotDataset 设计 <a class="header-anchor" href="#lerobotdataset-设计" aria-label="Permalink to &quot;LeRobotDataset 设计&quot;">​</a></h3><p>数据集通常由三个主要部分组成：</p><ul><li><p>表格数据(Tabular Data)：低维、高频数据（如关节状态和动作）存储在高效的内存映射文件中，并且通常交由 Hugging Face 更成熟的 datasets 库来管理，从而在有限的内存消耗下实现快速访问。</p></li><li><p>视觉数据(Visual Data)：为处理海量摄像头数据，各个图像帧会被合并并编码为 MP4 文件。同一 episode<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> 的帧始终会被归入同一个视频中, 不同摄像头的视频则会被分别保存起来。为减轻文件系统的负担，当视频数量超过一定阈值后，同一摄像头的视频会被进一步拆分并保存在多个子目录中。</p></li><li><p>元数据 (Metadata)：这是一组 JSON 文件，用于描述数据集的元数据结构。元数据相当于数据的“关系型表征“，与数据的表格形式和可视化呈现方式相对应。元数据包括各种特征的结构、帧率、标准化统计信息以及数据集的各个组成部分的边界信息。</p></li></ul><p>任何表格或视频所包含的信息通常并非仅来自某个单一的 episode，而是多个 episode 信息的整合。某个 LeRobotDataset 数据结构的示例：</p><ul><li><p><code>meta/info.json</code>: 包含了整个数据集的完整结构信息，包括所有元素的名称（如 <code>observation.state</code> 、 <code>action</code> 等）、它们的形状以及数据类型。此外，该文件还记录了诸如数据集的帧率( fps )、数据采集时的 lerobot 版本号，以及用于定位数据和视频文件的路径信息等关键数据。</p></li><li><p><code>meta/stats.json</code> ：该文件存储了整个数据集中每个特征的统计信息（均值、标准差、最小值、最大值）。这些数据被用于大多数策略模型的数据标准化处理。此外，还可以通过 <code>dataset.meta.stats</code> 来访问该文件中的数据。</p></li><li><p><code>meta/tasks.jsonl</code> ：该文件包含了将自然语言任务描述转换为整数任务索引的对应关系。这些整数任务索引对于基于任务的策略训练非常有用。</p></li><li><p><code>meta/episodes/*</code> 该目录包含了关于每一集的元数据，比如每 episode 的时长、所对应的任务类型，以及该集数据在数据集文件中的存储位置。为了提高可扩展性，这些信息被存储在多个文件中，而不是一个庞大的 JSON 文件里。</p></li><li><p><code>data/*</code>: 该部分包含核心的逐帧数据，这些数据以 Parquet 格式存储，从而实现了快速、高效的内存访问。为提升性能并处理大规模数据集，来自多个 episode 的数据会被合并到同一个大文件中。为了便于管理，这些大文件又被拆分成多个子目录。通常，一个文件会包含多个 episode 的数据。</p></li><li><p><code>videos/*</code> ：该目录包含所有视觉观测数据的 MP4 视频文件。与 <code>data/</code> 目录类似，多个 episode 视频片段被合并成一个 MP4 文件。这种处理方式大大减少了数据集中的文件数量，从而更符合现代文件系统的使用需求。</p></li></ul><h2 id="mujoco-仿真基础" tabindex="-1">MuJoCo 仿真基础 <a class="header-anchor" href="#mujoco-仿真基础" aria-label="Permalink to &quot;MuJoCo 仿真基础&quot;">​</a></h2><h2 id="isaac-sim-isaac-lab-并行仿真" tabindex="-1">Isaac Sim / Isaac Lab 并行仿真 <a class="header-anchor" href="#isaac-sim-isaac-lab-并行仿真" aria-label="Permalink to &quot;Isaac Sim / Isaac Lab 并行仿真&quot;">​</a></h2><h2 id="感知与传感器集成" tabindex="-1">感知与传感器集成 <a class="header-anchor" href="#感知与传感器集成" aria-label="Permalink to &quot;感知与传感器集成&quot;">​</a></h2><h2 id="sim-to-real-随机化、系统辨识与残差控制" tabindex="-1">Sim-to-real：随机化、系统辨识与残差控制 <a class="header-anchor" href="#sim-to-real-随机化、系统辨识与残差控制" aria-label="Permalink to &quot;Sim-to-real：随机化、系统辨识与残差控制&quot;">​</a></h2><h2 id="真机接口、安全与部署" tabindex="-1">真机接口、安全与部署 <a class="header-anchor" href="#真机接口、安全与部署" aria-label="Permalink to &quot;真机接口、安全与部署&quot;">​</a></h2><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>一次完整的任务执行轨迹。 <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',16)])])}const m=e(i,[["render",l]]);export{u as __pageData,m as default};
